use super::ImportSpec;

/// Parse one rendered import line back into its [`ImportSpec`] — the exact inverse of a single
/// iteration of [`crate::imports_fmt::render_import_block`]. Returns `None` for any line that is not one of the four
/// rendered forms, which is how [`crate::imports_fmt::strip_imports`] detects the end of the block.
pub fn parse_import_line(line: &str) -> Option<ImportSpec> {
    let t = line.trim();
    let src_end = t.strip_suffix("\";")?;
    let quote = src_end.rfind('"')?;
    let from = src_end[quote + 1..].to_string();
    let prefix = src_end[..quote].trim_end();
    let mk = |symbols: Vec<String>, type_only: bool, kind: &str| ImportSpec {
        from: from.clone(),
        symbols,
        type_only,
        kind: kind.to_string(),
    };
    // side-effect: `import "Y";`
    if prefix == "import" {
        return Some(mk(vec![], false, "side-effect"));
    }
    // every other form is `... from "Y";`
    let mid = prefix.strip_suffix("from")?.trim_end();
    // namespace: `import * as X`
    if let Some(ns) = mid.strip_prefix("import * as ") {
        return Some(mk(vec![ns.trim().to_string()], false, "namespace"));
    }
    // named, optionally type-only: `import [type] { a, b }`
    let (type_only, after_kw) = match mid.strip_prefix("import type ") {
        Some(rest) => (true, rest),
        None => (false, mid.strip_prefix("import ")?),
    };
    if let Some(inner) = after_kw.strip_prefix('{').and_then(|b| b.strip_suffix('}')) {
        let symbols = inner
            .split(',')
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        return Some(mk(symbols, type_only, "named"));
    }
    // default: `import X` (no braces, never type-only)
    if !type_only {
        return Some(mk(vec![after_kw.trim().to_string()], false, "default"));
    }
    None
}
